scent 15,12;18,12;18,15;15,15;15,12 cond="KT_QUEEN == 0"
enemy CR-080 15 12 cond="KT_QUEEN == 0"
text 15 11 "원탁 둘레 바닥에 반짝이는 고리. 일개미 하나가 끝없이 돈다 — 2백 년 묵은 케이크 부스러기 냄새를 따라." w=2 cond="KT_QUEEN == 0"
# ---------------------------------------------------------------- 1막 뒤 계엄군 관측조(창가 쌍안경 · 무전기)
enemy CR-401 24 9 dir=N cond="V_ACT >= 2"
enemy CR-403 28 11 dir=N cond="V_ACT >= 2"
# ---------------------------------------------------------------- 불을 먼저 켰다(여왕 전): 발전기 열 · 진동을 따라 개미 줄이 연회장까지
scent 2,19;10,11;20,11;26,5;27,4 cond="KT_HEAT == 1 and KT_QUEEN == 0"
enemy CR-080 10 11 cond="KT_HEAT == 1 and KT_QUEEN == 0"
enemy CR-080 20 11 cond="KT_HEAT == 1 and KT_QUEEN == 0"
